def caesar(s: str, k: int) -> str:
    k %= 26
    res = []
    for ch in s:
        if 'a' <= ch <= 'z':
            res.append(chr((ord(ch) - ord('a') + k) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            res.append(chr((ord(ch) - ord('A') + k) % 26 + ord('A')))
        else:
            res.append(ch)
    return ''.join(res)
